// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { cn } from '@/shared/utils/cn'

import { geometry, type Style } from './script'

/** The extension's styled QR render: module and eye shapes, gradient ink and background. */
export function StyledQr({
  payload,
  style,
  id,
  className,
}: {
  payload: string
  style: Style
  id: string
  className?: string
}) {
  const shape = geometry(payload, style)
  const ink = style.gradient === 'none' ? style.fg : `url(#${id})`
  const eyeInk = style.eyeColor ?? ink
  return (
    <svg
      viewBox={`0 0 ${shape.width} ${shape.width}`}
      className={cn('block size-full', className)}
      aria-hidden
    >
      {style.gradient === 'linear' ? (
        <defs>
          <linearGradient
            id={id}
            gradientUnits="userSpaceOnUse"
            x1="0"
            y1="0"
            x2={shape.width}
            y2={shape.width}
          >
            <stop offset="0" stopColor={style.fg} />
            <stop offset="1" stopColor={style.fg2} />
          </linearGradient>
        </defs>
      ) : style.gradient === 'radial' ? (
        <defs>
          <radialGradient
            id={id}
            gradientUnits="userSpaceOnUse"
            cx={shape.width / 2}
            cy={shape.width / 2}
            r={shape.width / 1.4}
          >
            <stop offset="0" stopColor={style.fg} />
            <stop offset="1" stopColor={style.fg2} />
          </radialGradient>
        </defs>
      ) : null}
      <rect width={shape.width} height={shape.width} fill={style.bg} />
      <path d={shape.body} fill={ink} />
      {shape.eyes.map((eye, index) => (
        <g key={index}>
          <path d={eye.ring} fill={eyeInk} fillRule="evenodd" />
          <path d={eye.pupil} fill={eyeInk} />
        </g>
      ))}
    </svg>
  )
}
